:root {
  /* Primitives */
  --nw-gray-0: #ffffff;
  --nw-gray-100: #e4e7eb;
  --nw-gray-900: #1f2933;
  --nw-gray-950: #111827;
  --nw-blue-400: #6b93f5;
  --nw-blue-600: #1f5ae0;
  --nw-space-1: 0.25rem;
  --nw-space-2: 0.5rem;
  --nw-space-3: 0.75rem;
  --nw-space-4: 1rem;

  /* Semantic tokens: light theme, comfortable density */
  --nw-color-surface: var(--nw-gray-0);
  --nw-color-text: var(--nw-gray-900);
  --nw-color-action-bg: var(--nw-blue-600);
  --nw-color-action-text: var(--nw-gray-0);
  --nw-space-control-y: var(--nw-space-2);
  --nw-space-control-x: var(--nw-space-4);
}

/* Add the dark theme here */

/* Add the compact density here */

/* Components (don't change these) */
.card {
  background: var(--nw-color-surface);
  color: var(--nw-color-text);
  padding: 16px;
  border-radius: 8px;
  margin-bottom: 16px;
}
.card h3 { margin: 0 0 12px; }
.nw-button {
  --nw-button-bg: var(--nw-color-action-bg);
  --nw-button-text: var(--nw-color-action-text);
  background: var(--nw-button-bg);
  color: var(--nw-button-text);
  padding: var(--nw-space-control-y) var(--nw-space-control-x);
  border: 0;
  border-radius: 6px;
  font: inherit;
}

